{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Loteprednol etabonate, a corticosteroid ester prodrug, showed very low oral bioavailability in healthy volunteers after a 40 mg oral dose; this supports low F for the query's ester/acetal corticosteroid prodrug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Mometasone, a halogenated corticosteroid ester, has oral bioavailability <1% in humans; this supports low F for the query, which shares the soft-steroid prodrug design.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Beclomethasone dipropionate, a corticosteroid diester prodrug, has an absolute oral bioavailability of 15% in humans, below the 20% threshold; supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Deflazacort, the most similar analogue, had 68% absolute oral bioavailability in volunteers; this is contradictory evidence for low, but its oxazoline prodrug and lack of soft-steroid first-pass inactivation limit transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is a corticosteroid acetal/ester prodrug (ciclesonide-like). The most mechanistically relevant soft-steroid prodrug analogues (loteprednol, beclomethasone dipropionate, mometasone) show low or very low oral bioavailability, often below 20%, due to extensive first-pass metabolism. High-F plain corticosteroids are less transferable because they lack the ester/acetal prodrug and soft-steroid inactivation design.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for ciclesonide itself in the provided evidence.",
    "First-pass metabolism of the specific isobutyryl ester and cyclohexyl acetal in gut/liver is inferred from analogues, not directly measured.",
    "The highest-similarity analogue (deflazacort) shows high F, leaving residual uncertainty about prodrug class effects."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

